  "claims": [
    {
      "id": "rc:3436545216",
      "kind": "correctness",
      "harm": "direct GetMockTime call in tx_pool test can silently cause bugs if mocktime is unset, bypasses the system time sanitizer, and returns a duration instead of a time point",
      "quote": "the call to GetMockTime here looks wrong for several reasons: It directly access the test-only global of the mock time, which may be 0, and thus may lead to silent bugs if mocktime was not used here? It side-steps the g_used_system_time runtime sanitizer.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:3438787890"
      ],
      "fix_pushed": true,
      "settled_by_id": "rc:3438787890",
      "settled_by_quote": "Makes sense, switched GetMockTime() -> Now()"
    },
    {
      "id": "c:4780411600",
      "kind": "interface",
      "harm": "requiring users to manage clock time across multiple separate places is cumbersome and error-prone",
      "quote": "This could get a bit annoying and potentially dangerous when users need to start managing clocks across multiple places.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "r:4588310492"
      ],
      "fix_pushed": false,
      "settled_by_id": "r:4588310492",
      "settled_by_quote": "My instinct is that it doesn't because if you're creating multiple chainstate managers or other objects that accept times, and your application needs artificial times instead of the current clock time, I wouldn't assume that multiple objects would want to have the same time set."
    },
    {
      "id": "c:5313546704",
      "kind": "approach",
      "harm": "the PR may no longer be relevant following the merge of PR 35496, and it conflicts conceptually with PR 35906",
      "quote": "That one was merged, so is this here still relevant? Also, this conflicts with https://github.com/bitcoin/bitcoin/pull/35906#discussion_r3726539086",
      "blocking": false,
      "status": "open",
      "author_replies": [],
      "fix_pushed": false,
      "settled_by_id": "",
      "settled_by_quote": ""
    }
  ],
  "support": [
    {
      "id": "c:4763429282",
      "verdict": "",
      "reason": "prefers setting clock time on chainman over setting it in options because it can be updated repeatedly and matches current global mocktime mechanics",
      "substantive": true
    }
  ],
  "notes": "Initial record setup. Maflcko's query regarding relevance and conceptual conflict with PR 35906 remains open without an author reply."
